import React, { useRef, useState } from 'react';
import './ImageLinkForm.css';

const ImageLinkForm = ({ onInputChange, onButtonSubmit, onFileChange }) => {
  const fileInputRef = useRef(null);
  const [mode, setMode] = useState('browse');

  const handleBrowseClick = () => {
    fileInputRef.current.click();
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter') {
      onButtonSubmit();
    }
  };

  return (
    <div className='ilf-container'>
      <p className='ilf-title'>
        Detect faces in any picture — paste a link or upload from your device
      </p>

      {/* Mode Toggle */}
      <div className='ilf-toggle-wrap'>
        <div className='ilf-toggle'>
          <button
            className={`ilf-toggle-btn ${mode === 'url' ? 'ilf-toggle-active' : ''}`}
            onClick={() => setMode('url')}
          >
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"/>
              <path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"/>
            </svg>
            Paste Link
          </button>
          <button
            className={`ilf-toggle-btn ${mode === 'browse' ? 'ilf-toggle-active' : ''}`}
            onClick={() => setMode('browse')}
          >
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/>
              <polyline points="17 8 12 3 7 8"/>
              <line x1="12" y1="3" x2="12" y2="15"/>
            </svg>
            Upload
          </button>
        </div>
      </div>

      {/* Content Area */}
      <div className='ilf-content'>
        {mode === 'url' ? (
          <div className='ilf-url-form'>
            <input
              className='ilf-url-input'
              type='text'
              placeholder='https://example.com/photo.jpg'
              onChange={onInputChange}
              onKeyDown={handleKeyDown}
            />
            <button className='ilf-detect-btn' onClick={onButtonSubmit}>
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <circle cx="11" cy="11" r="8"/>
                <line x1="21" y1="21" x2="16.65" y2="16.65"/>
              </svg>
              Detect
            </button>
          </div>
        ) : (
          <div className='ilf-upload-area' onClick={handleBrowseClick}>
            <div className='ilf-upload-icon'>
              <svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.2" strokeLinecap="round" strokeLinejoin="round">
                <rect x="3" y="3" width="18" height="18" rx="2" ry="2"/>
                <circle cx="8.5" cy="8.5" r="1.5"/>
                <polyline points="21 15 16 10 5 21"/>
              </svg>
            </div>
            <p className='ilf-upload-text'>Click to upload an image</p>
            <p className='ilf-upload-hint'>JPG, PNG, WEBP up to 10MB</p>
          </div>
        )}
        <input
          ref={fileInputRef}
          type='file'
          accept='image/*'
          style={{ display: 'none' }}
          onChange={onFileChange}
        />
      </div>
    </div>
  );
};

export default ImageLinkForm;
